/**
 * Two-factor enrolment panel (settings → 安全).
 *
 * The secret is generated by the backend, shown once as an `otpauth://` QR
 * code plus a manual key, and only becomes a binding after one live code has
 * been confirmed. Nothing here decides security on its own: the backend keeps
 * the sealed secret and re-checks every code on unlock.
 */
import { Copy, RefreshCw, ShieldCheck, ShieldOff, X } from 'lucide-react'
import { useEffect, useState } from 'react'
import QRCode from 'react-qr-code'
import { ApiError, api, copyText } from '../lib/api'
import { useI18n } from '../lib/i18n'
import { toast } from '../lib/toast'
import type { StateInfo, TotpBinding, TotpStatus } from '../lib/types'
import { cn } from '../lib/utils'
import { Section, Spinner } from './primitives'

function message(error: unknown, fallback: string) {
  return error instanceof ApiError ? error.message : fallback
}

/** Seconds left in the current 30-step, so the operator knows when it rolls. */
function useStepCountdown(period: number) {
  const [left, setLeft] = useState(() => period - (Math.floor(Date.now() / 1000) % period))
  useEffect(() => {
    const timer = window.setInterval(() => {
      setLeft(period - (Math.floor(Date.now() / 1000) % period))
    }, 1000)
    return () => window.clearInterval(timer)
  }, [period])
  return left
}

export function TotpPanel({ onState }: { onState: (state: StateInfo) => void }) {
  const { t } = useI18n()
  const [status, setStatus] = useState<TotpStatus | null>(null)
  const [binding, setBinding] = useState<TotpBinding | null>(null)
  const [code, setCode] = useState('')
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState('')
  const [dropping, setDropping] = useState(false)
  const [dropPassword, setDropPassword] = useState('')
  const [dropCode, setDropCode] = useState('')
  const period = status?.period ?? 30
  const digits = status?.digits ?? 6
  const left = useStepCountdown(period)

  useEffect(() => {
    let cancelled = false
    api
      .getTotpStatus()
      .then((result) => {
        if (!cancelled) setStatus(result.status)
      })
      .catch((error) => {
        if (!cancelled) setError(message(error, t('无法读取两步验证状态')))
      })
    return () => {
      cancelled = true
    }
  }, [t])

  async function begin() {
    setBusy(true)
    setError('')
    try {
      const result = await api.startTotpBind()
      setBinding(result)
      setStatus(result)
      setCode('')
    } catch (error) {
      setError(message(error, t('生成二维码失败')))
    } finally {
      setBusy(false)
    }
  }

  async function confirm() {
    if (code.length !== digits) {
      setError(t('请输入验证器上的 {n} 位动态验证码', { n: digits }))
      return
    }
    setBusy(true)
    setError('')
    try {
      const result = await api.verifyTotpBind(code)
      setStatus(result.status)
      setBinding(null)
      setCode('')
      onState(result.state)
      toast.success(t('两步验证已开启'), t('下次解锁需要打开密码加动态验证码。'))
    } catch (error) {
      setError(message(error, t('验证失败')))
    } finally {
      setBusy(false)
    }
  }

  async function cancel() {
    setBusy(true)
    try {
      const result = await api.cancelTotpBind()
      setStatus(result.status)
    } catch (error) {
      setError(message(error, t('取消失败')))
    } finally {
      setBinding(null)
      setCode('')
      setBusy(false)
    }
  }

  async function drop() {
    if (!dropPassword) {
      setError(t('请输入当前打开密码'))
      return
    }
    if (dropCode.length !== digits) {
      setError(t('请输入验证器上的 {n} 位动态验证码', { n: digits }))
      return
    }
    setBusy(true)
    setError('')
    try {
      const result = await api.disableTotp(dropPassword, dropCode)
      setStatus(result.status)
      setDropping(false)
      setDropPassword('')
      setDropCode('')
      onState(result.state)
      toast.info(t('两步验证已关闭'), t('之后只需输入打开密码即可解锁。'))
    } catch (error) {
      setError(message(error, t('关闭失败')))
    } finally {
      setBusy(false)
    }
  }

  const enabled = Boolean(status?.enabled)

  return (
    <Section
      title={t('两步验证（Authenticator）')}
      description={t(
        '开启后，解锁保险库需要打开密码加上验证器上每 {n} 秒更换的动态验证码；兼容 Google Authenticator、微软身份验证器、FreeOTP 等标准 TOTP 应用。',
        { n: period },
      )}
      action={
        status ? (
          <span className={cn('chip', enabled ? 'chip-mint' : '')}>
            <ShieldCheck
              className={cn('size-3', enabled ? 'text-teal-300' : 'text-ice-600')}
            />
            {enabled ? t('已开启') : t('未开启')}
          </span>
        ) : null
      }
    >
      {error && (
        <p className="mb-3 text-[0.71875rem] leading-relaxed text-rose-300">{error}</p>
      )}

      {!status ? (
        <p className="flex items-center gap-2 text-[0.75rem] text-ice-500">
          <Spinner className="size-3.5" />
          {t('正在读取状态…')}
        </p>
      ) : enabled && !dropping ? (
        <div className="flex flex-wrap items-center justify-between gap-3">
          <p className="min-w-0 flex-1 text-[0.75rem] leading-relaxed text-ice-500">
            {t('绑定时间：{time}。修改打开密码不会影响已绑定的验证器；手机丢了可用恢复密钥重设密码，同时会自动解除绑定。', {
              time: status.enabled_at || '-',
            })}
          </p>
          <button
            type="button"
            onClick={() => {
              setDropping(true)
              setError('')
            }}
            className="btn-ghost inline-flex h-8 shrink-0 items-center gap-1.5 rounded-lg border border-line px-3 text-[0.71875rem] transition hover:bg-[var(--msv-tint-strong)]"
          >
            <ShieldOff className="size-3.5" />
            {t('关闭两步验证')}
          </button>
        </div>
      ) : (
        <div className="space-y-3">
          {!binding && !dropping && (
            <>
              <p className="text-[0.75rem] leading-relaxed text-ice-500">
                {t(
                  '开启前请准备一台装了验证器应用的手机。点击生成二维码后，{n} 分钟内扫码并输入一次动态验证码即可完成绑定；期间不输入正确验证码不会生效。',
                  { n: status.pending_minutes },
                )}
              </p>
              <button
                type="button"
                disabled={busy}
                onClick={begin}
                className="btn-primary inline-flex h-8 items-center gap-1.5 rounded-lg px-3 text-[0.71875rem] font-semibold transition hover:brightness-105 disabled:opacity-50"
              >
                {busy ? <Spinner className="size-3.5" /> : <RefreshCw className="size-3.5" />}
                {t('生成二维码并开始绑定')}
              </button>
            </>
          )}

          {dropping && (
            <div className="grid gap-3 sm:grid-cols-[minmax(0,1fr)_120px_auto]">
              <div>
                <label className="field-label" htmlFor="totp-drop-password">
                  {t('当前打开密码')}
                </label>
                <input
                  id="totp-drop-password"
                  className="msv-input"
                  type="password"
                  autoComplete="current-password"
                  value={dropPassword}
                  onChange={(event) => {
                    setDropPassword(event.target.value)
                    setError('')
                  }}
                />
              </div>
              <div>
                <label className="field-label" htmlFor="totp-drop-code">
                  {t('动态验证码')}
                </label>
                <input
                  id="totp-drop-code"
                  className="msv-input font-mono tracking-[0.2em]"
                  inputMode="numeric"
                  maxLength={digits}
                  placeholder={'0'.repeat(digits)}
                  value={dropCode}
                  onChange={(event) => {
                    setDropCode(event.target.value.replace(/\D/g, '').slice(0, digits))
                    setError('')
                  }}
                />
              </div>
              <div className="flex items-end gap-2">
                <button
                  type="button"
                  disabled={busy}
                  onClick={drop}
                  className="btn-primary inline-flex h-9 items-center gap-1.5 rounded-lg px-3 text-[0.71875rem] font-semibold transition hover:brightness-105 disabled:opacity-50"
                >
                  {busy ? <Spinner className="size-3.5" /> : <ShieldOff className="size-3.5" />}
                  {t('确认关闭')}
                </button>
                <button
                  type="button"
                  onClick={() => {
                    setDropping(false)
                    setDropPassword('')
                    setDropCode('')
                    setError('')
                  }}
                  className="inline-flex h-9 items-center gap-1 rounded-lg px-2 text-[0.71875rem] text-ice-500 transition hover:bg-[var(--msv-tint)] hover:text-ice-200"
                >
                  <X className="size-3.5" />
                  {t('取消')}
                </button>
              </div>
            </div>
          )}

          {binding && (
            <div className="flex flex-wrap items-start gap-4">
              <div className="rounded-xl border border-line bg-white p-3">
                <QRCode value={binding.uri} size={168} bgColor="#ffffff" fgColor="#0b1220" />
              </div>
              <ol className="min-w-[240px] flex-1 space-y-2 text-[0.75rem] leading-relaxed text-ice-400">
                <li>
                  {t('1. 在验证器应用里扫码；无法扫码时选「手动输入密钥」。')}
                </li>
                <li>
                  {t('2. 密钥也可以直接复制：')}
                  <div className="mt-1 flex items-center gap-1.5">
                    <code className="min-w-0 flex-1 truncate rounded-md border border-line bg-[var(--msv-tint-strong)] px-2 py-1 font-mono text-[0.71875rem] text-ice-200">
                      {binding.secret}
                    </code>
                    <button
                      type="button"
                      aria-label={t('复制密钥')}
                      className="grid size-7 shrink-0 place-items-center rounded-md text-ice-500 transition hover:bg-[var(--msv-tint)] hover:text-ice-200"
                      onClick={async () => {
                        try {
                          await copyText(binding.secret)
                          toast.success(t('密钥已复制'), t('粘贴到验证器的「手动输入密钥」里。'))
                        } catch (error) {
                          toast.error(t('复制失败'), message(error, t('请手动抄写密钥')))
                        }
                      }}
                    >
                      <Copy className="size-3.5" />
                    </button>
                  </div>
                </li>
                <li>
                  {t('3. 输入验证器当前显示的 {n} 位验证码以确认绑定。', {
                    n: binding.digits,
                  })}
                </li>
                <li className="text-ice-600">
                  {t('账户名：{name} · 算法 {algorithm} · 有效期 {n} 秒', {
                    name: binding.account,
                    algorithm: binding.algorithm,
                    n: binding.period,
                  })}
                </li>
              </ol>
            </div>
          )}

          {binding && (
            <div className="flex flex-wrap items-end gap-3">
              <div className="w-[150px]">
                <label className="field-label" htmlFor="totp-code">
                  {t('动态验证码')}
                </label>
                <input
                  id="totp-code"
                  className="msv-input font-mono text-[1.0625rem] tracking-[0.3em]"
                  inputMode="numeric"
                  autoComplete="one-time-code"
                  maxLength={digits}
                  placeholder={'0'.repeat(digits)}
                  value={code}
                  onChange={(event) => {
                    setCode(event.target.value.replace(/\D/g, '').slice(0, digits))
                    setError('')
                  }}
                  onKeyDown={(event) => {
                    if (event.key === 'Enter') confirm()
                  }}
                />
              </div>
              <button
                type="button"
                disabled={busy || code.length !== digits}
                onClick={confirm}
                className="btn-primary inline-flex h-9 items-center gap-1.5 rounded-lg px-3 text-[0.71875rem] font-semibold transition hover:brightness-105 disabled:opacity-50"
              >
                {busy ? <Spinner className="size-3.5" /> : <ShieldCheck className="size-3.5" />}
                {t('验证并开启')}
              </button>
              <button
                type="button"
                disabled={busy}
                onClick={begin}
                className="inline-flex h-9 items-center gap-1.5 rounded-lg px-2.5 text-[0.71875rem] text-ice-500 transition hover:bg-[var(--msv-tint)] hover:text-ice-200 disabled:opacity-50"
              >
                <RefreshCw className="size-3.5" />
                {t('重新生成')}
              </button>
              <button
                type="button"
                onClick={cancel}
                className="inline-flex h-9 items-center gap-1 rounded-lg px-2.5 text-[0.71875rem] text-ice-500 transition hover:bg-[var(--msv-tint)] hover:text-ice-200"
              >
                <X className="size-3.5" />
                {t('取消')}
              </button>
              <span className="ml-auto text-[0.6875rem] text-ice-600">
                {t('本码剩余 {n} 秒', { n: left })}
              </span>
            </div>
          )}
        </div>
      )}
    </Section>
  )
}
